def amicable_numbers_sum(limit: int) -> int:
    def get_sum_of_divisors(n: int) -> int:
        # Optimization: sum of divisors excluding the number itself
        total = 1
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                total += i
                if i*i != n:
                    total += n // i
        return total

    total_sum = 0
    # Use a set to track numbers already counted (since amicable pairs are bidirectional)
    seen = set()

    for a in range(1, limit + 1):
        if a in seen:
            continue

        b = get_sum_of_divisors(a)
        # Amicable condition: sum_div(a) == b AND sum_div(b) == a AND a != b
        if b > 1 and b != a and get_sum_of_divisors(b) == a:
            total_sum += a
            seen.add(a)
            # If the partner is within range, we don't add it again immediately 
            # but ensure it's marked so we don't process it as 'a' later
            if b <= limit:
                seen.add(b)

    return total_sum

